import { AsyncLocalStorage } from 'node:async_hooks';
import { EventEmitter } from 'node:events';
import { promisify } from 'node:util';
import { setTimeout as delay } from 'node:timers/promises';
const als = new AsyncLocalStorage<string>();
function rec(tag: string): void { console.log(tag + '=' + String(als.getStore())); }
function sleep(ms: number): Promise<number> { return new Promise<number>((r: (v: number) => void): void => { setTimeout((): void => { r(ms); }, ms); }); }
async function* gen(): AsyncGenerator<number> { await sleep(1); rec('gen'); yield 1; }
function cbApi(v: number, cb: (err: any, v?: number) => void): void { setTimeout((): void => { cb(null, v * 2); }, 1); }
const promisedApi = promisify(cbApi);
async function main(): Promise<void> {
  await als.run('E', async (): Promise<void> => {
    for await (const _x of gen()) { rec('for-await'); }
    const em = new EventEmitter();
    em.on('e', (): void => { rec('emitter-sync'); });
    await delay(1);
    em.emit('e');
    const doubled = await promisedApi(21);
    rec('promisify-' + doubled);
  });
  rec('outside');
}
